import sys

def solution(input_data):
    n, m = map(int, input_data.split('\n')[0].split())
    offers = []
    lines = input_data.split('\n')[1:]
    for line in lines:
        if line:
            parts = list(map(int, line.split()))
            if len(parts) == 2:
                offers.append((parts[0], parts[1]))

    result = []

    for x in range(1, n + 1):
        occupied = False  # Track if current day is already occupied
        days_occupied = 0
        # Track accepted offers as a set of intervals
        accepted = set()

        for l, r in offers:
            # Check duration condition
            duration = r - l + 1
            if duration < x:
                continue

            # Check if this offer overlaps with any accepted offer
            overlap = False
            for (start, end) in accepted:
                start, end = int(start), int(end)
                if max(start, l) <= min(end, r):
                    overlap = True
                    break

            if not overlap:
                accepted.add((l, r))
                days_occupied += duration
                # Update tracking for future overlap checks
                for d in range(l, r + 1):
                    occupied = True
            else:
                # Omit the occupied days in range
                for d in range(l, r + 1):
                    occupied = False

        result.append(str(days_occupied))
        if x < n:
            result.append('\n')
        else:
            result.append('\n')  # trailing newline

    return ''.join(result)

# Understanding the optimization needed

def solution(grid_string):
    lines = grid_string.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]

    # Find all free cells and their bounds
    all_free = []
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.':
                all_free.append((r, c))

    if not all_free:
        return '\n'.join(''.join(row) for row in grid)

    # Find bounding box of all free cells
    min_r, min_c = min(all_free)[0], min(all_free)[1]
    max_r, max_c = max(all_free)[0], max(all_free)[1]

    # Remove all walls within the bounding box
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if grid[r][c] == '*':
                grid[r][c] = '.'

    return '\n'.join(''.join(row) for row in grid)

