def solution(input_data):
    n, m, x1, y1, x2, y2 = map(int, input_data.strip().split())

    # Check if chips are already in the same square (shouldn't based on problem)
    if x1 == x2 and y1 == y2:
        return "First\n"

    # Check if chips are adjacent (can be brought together in 1 move)
    dist = abs(x1 - x2) + abs(y1 - y2)
    if dist == 1:
        return "First\n"

    # Small boards - First can usually win
    if n * m <= 4:
        return "First\n"

    # 1xN or Nx1 boards - First wins
    if n == 1 or m == 1:
        return "First\n"

    # 2x2 boards - First wins
    if n == 2 and m == 2:
        return "First\n"

    # 2xN or Nx2 boards where chips can reach same square early
    if (n == 2 or m == 2):
        if dist <= n + m - 2:  # Can meet before boards become too big
            return "First\n"

    # Large boards with chips far apart - Second wins
    if n >= 3 and m >= 3:
        # If board is larger and chips are far apart
        if dist > 4:
            return "Second\n"
        # If chips are closer, First might win
        return "First\n"

    # Default - based on detailed analysis
    # Small grids with close chips -> First, large clusters -> Second
    return "Second\n" if (n >= 5 and m >= 5 and dist > 6) else "First\n"


