def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    def check_gp(arr):
        m = len(arr)
        if m <= 2:
            return True

        # Handle case where first element is 0
        if arr[0] == 0:
            # All elements must be 0
            return all(x == 0 for x in arr)

        # For a[0] != 0, if any element is 0, all subsequent must be 0
        for i in range(m - 1):
            if arr[i] == 0:
                rest_are_zero = True
                for j in range(i + 1, m):
                    if arr[j] != 0:
                        rest_are_zero = False
                        break
                if not rest_are_zero:
                    return False
                # If we reach here, all remaining after i are 0, and since arr[i]=0,
                # we need to check if ratio 0 is consistent
                # Since arr[i] = 0 and arr[0] != 0, this means arr[0]*0 = arr[1]*0 which is always true
                # But for geometric progression, once an element is 0, all must be 0
                for j in range(i + 1, m):
                    if arr[j] != 0:
                        return False
                return True

        # General case: use cross multiplication to check geometric progression
        # arr[i+1] * arr[0] == arr[i] * arr[1]
        for i in range(m - 1):
            if arr[i] * arr[0] != arr[i + 1] * arr[1]:
                return False
        return True

    # Check if already a GP
    if check_gp(arr):
        return "0\n"

    # Try removing each element
    for i in range(n):
        remaining = arr[:i] + arr[i+1:]
        if check_gp(remaining):
            return "1\n"

    return "2\n"

def solution(input_data):
    import sys
    sys.setrecursionlimit(500000)

    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(2 * m)]

    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]

        lits = []
        for lit in literals:
            idx = abs(lit) - 1
            is_neg = lit < 0
            lits.append((idx, is_neg))

        for i in range(k):
            idx_i, neg_i = lits[i]
            lit_i = 2 * idx_i + (1 if neg_i else 0)
            not_lit_i = lit_i ^ 1

            for j in range(k):
                if i == j:
                    continue
                idx_j, neg_j = lits[j]
                lit_j = 2 * idx_j + (1 if neg_j else 0)
                adj[not_lit_i].append(lit_j)

    visited = [False] * (2 * m)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(2 * m):
        if not visited[i]:
            dfs1(i)

    rev_adj = [[] for _ in range(2 * m)]
    for u in range(2 * m):
        for v in adj[u]:
            rev_adj[v].append(u)

    scc = [-1] * (2 * m)
    visited_scc = [False] * (2 * m)
    scc_id = 0

    def dfs2(u):
        scc[u] = scc_id
        visited_scc[u] = True
        for v in rev_adj[u]:
            if not visited_scc[v]:
                dfs2(v)

    for i in reversed(order):
        if not visited_scc[i]:
            dfs2(i)
            scc_id += 1

    for i in range(m):
        if scc[2 * i] == scc[2 * i + 1]:
            return "NO"

    assignment = [0] * m
    for i in range(m):
        if scc[2 * i] < scc[2 * i + 1]:
            assignment[i] = 1

    return "YES\n" + "".join(map(str, assignment))


