    # These are positions that would create a fixed point if we put value = position index there
    r = 0
    for pos in unknown_positions:
        if pos in available_values:
            r += 1

    # Precompute factorials for combinations
    fact = [1] * (k + 1)
    for i in range(1, k + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    def power(a, b, mod):
        result = 1
        a %= mod
        while b > 0:
            if b % 2 == 1:
                result = result * a % mod
            a = a * a % mod
            b //= 2
        return result

    def modInverse(a, mod):
        return power(a, mod - 2, mod)

    def nCr_mod(n, r, mod, fact):
        if r < 0 or r > n:
            return 0
        return fact[n] * modInverse(fact[r] * fact[n - r] % mod, mod) % mod

    # Compute answer using inclusion-exclusion:
    # Sum_{j=0}^{r} (-1)^j * C(r, j) * (k-j)!
    # This counts assignments where no fixed point is created among the r conflict positions
    ans = 0
    for j in range(r + 1):
        term = nCr_mod(r, j, MOD, fact) * fact[k - j] % MOD
        if j % 2 == 1:
            ans = (ans - term + MOD) % MOD
        else:
            ans = (ans + term) % MOD

    return str(ans) + '\n'

