def is_valid(a):
    """Check if array is valid without any swap"""
    prev_b = 0

    for i in range(len(a) - 1):
        current_b = a[i] - prev_b
        if current_b < 0:
            return False
        prev_b = current_b

    # Final check: last pile must equal the operations on pair (n-1, n)
    return a[-1] == prev_b

def can_fix_with_swap(a, n):
    """Check if any adjacent swap makes the array valid"""
    original_b = [0] * n  # Precompute original b values

    for i in range(len(a) - 1):
        if i == 0:
            original_b[i] = a[i]
        else:
            original_b[i] = a[i] - original_b[i-1]

    # Check if originally valid
    is_orig_valid = True
    for i in range(len(original_b) - 1):
        if original_b[i] < 0:
            is_orig_valid = False
            break
    is_orig_valid = is_orig_valid and (a[-1] == original_b[-2])

    if is_orig_valid:
        return True

    # Try each adjacent swap
    for i in range(n - 1):
        # Swap positions i and i+1
        new_a = a.copy()
        new_a[i], new_a[i + 1] = new_a[i + 1], new_a[i]

        if is_valid(new_a):
            return True

    return False

