    n, m, l = len(s1), len(s2), len(virus)

    if l == 0:
        # If virus is empty, just return empty string (actually virus length >= 1 per constraints)
        return "0"

    # KMP failure function
    fail = [0] * l
    k = 0
    for i in range(1, l):
        while k > 0 and virus[k] != virus[i]:
            k = fail[k - 1]
        if virus[k] == virus[i]:
            k += 1
        fail[i] = k

    # Transition table: next_state[current_match_len][char_ord]
    next_state = [[0] * 128 for _ in range(l)]
    for state in range(l):
        for c in range(128):
            k = state
            while k > 0 and virus[k] != chr(c):
                k = fail[k - 1]
            if virus[k] == chr(c):
                k += 1
            else:
                k = 0
            next_state[state][c] = k

    # dp[i][j][k] = max LCS length using s1[:i] and s2[:j] with match state k
    dp = [[[0] * l for _ in range(m + 1)] for _ in range(n + 1)]
    # parent[i][j][k] = ('action', prev_i, prev_j, prev_k) where action: 1=s1, 2=s2, 3=both

    dp[0][0][0] = 0
    parent = [[[None] * l for _ in range(m + 1)] for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(l):
                # Don't include (0,0,0) as parent
                if (i, j, k) == (0, 0, 0):
                    continue

                best_len = 0
                best_parent = None

                # Option 1: from dp[i-1][j] skip s1[i-1]
                if i > 0:
                    new_k = next_state[k][ord(s1[i-1])]
                    if new_k < l:
                        if dp[i-1][j][new_k] > best_len:
                            best_len = dp[i-1][j][new_k]
                            best_parent = (1, i-1, j, new_k)

                # Option 2: from dp[i][j-1] skip s2[j-1]
                if j > 0 and best_parent is None:
                    new_k = next_state[k][ord(s2[j-1])]
                    if new_k < l:
                        if dp[i][j-1][new_k] > best_len:
                            best_len = dp[i][j-1][new_k]
                            best_parent = (2, i, j-1, new_k)

                # Option 3: from dp[i-1][j-1] if both chars same
                if i > 0 and j > 0 and s1[i-1] == s2[j-1] and best_parent is None:
                    if dp[i-1][j-1][k] > 0:
                        new_k = next_state[k][ord(s1[i-1])]
                        if new_k < l:
                            if dp[i-1][j-1][k] + 1 > best_len:
                                best_len = dp[i-1][j-1][k] + 1
                                best_parent = (3, i-1, j-1, k)

                dp[i][j][k] = best_len
                parent[i][j][k] = best_parent

    # Find maximum dp[n][m][k]
    max_len = 0
    best_k = 0
    for k in range(l):
        if dp[n][m][k] > max_len:
            max_len = dp[n][m][k]
            best_k = k

    if max_len == 0:
        return "0"

    # Reconstruct LCS
    result = []
    i, j, k = n, m, best_k

    # Backtrack
    while (i > 0 or j > 0) and dp[i][j][k] > 0:
        p = parent[i][j][k]
        if p is None:
            break

        action, pi, pj, pk = p

        if action == 1:  # Skip s1[i-1], came from (i-1, j, k_internal where transition led to (i,j,k))
            pi -= 1
            k = pk
        elif action == 2:  # Skip s2[j-1]
            pj -= 1
            k = pk
        elif action == 3:  # Match s1[i-1] = s2[j-1]
            result.append(s1[i-1])
            i -= 1
            j -= 1

    return ''.join(reversed(result))


