            self.u = u
            self.v = v
            self.cap = cap
            self.flow = 0
            self.rev = None
            self.capacity = cap  # store original capacity

    def add_edge(u, v, cap):
        gu = Edge(u, v, cap)
        gv = Edge(v, u, 0)
        gu.rev = len(gv)
        gv.rev = len(gu)
        g[u].append(gu)
        g[v].append(gv)

    g = [[] for _ in range(2 * n + 2)]
    src, sink = 0, 2 * n + 1

    for i in range(n):
        # From source to city i (as sender)
        add_edge(src, i + 1, a[i])
        # From city i+n (as receiver) to sink
        add_edge(i + 1 + n, sink, b[i])
        # From sender i to receiver j if they can reach
        for j in range(n):
            if adj[i][j]:
                add_edge(i + 1, j + 1 + n, float('inf'))

    def bfs():
        level = [-1] * (2 * n + 2)
        level[src] = 0
        queue = [src]
