            v = queue.pop(0)
            for e in g[v]:
                if e.cap - e.flow > 0 and level[e.v] < 0:
                    level[e.v] = level[v] + 1
                    queue.append(e.v)
        return level[sink] >= 0

    def dfs(v, f, it):
        if v == sink or f == 0:
            return f
        for i in range(it[v], len(g[v])):
            it[v] = i
            e = g[v][i]
            if level[e.v] == level[v] + 1 and e.cap - e.flow > 0:
                d = dfs(e.v, min(f, e.cap - e.flow), it)
                if d > 0:
                    e.flow += d
                    g[e.v][e.rev].flow -= d
                    return d
        return 0

    flow = 0
    while bfs():
        it = [0] * (2 * n + 2)
        while True:
            d = dfs(src, float('inf'), it)
            if d == 0:
                break
            flow += d

    if flow != sum(a):
