    for i in range(n):
        for e in g[i + 1]:
            if e.v > n and e.v <= 2 * n:
                j = e.v - (n + 1)
                ans[i][j] = e.flow

    result = "YES\n" + "\n".join(
        " ".join(map(str, row)) for row in ans
    )
    return result

