def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        operations.append((parts[0], parts[1], parts[2]))

    min_steps = [-1] * (m + 1)
    current_reachable: Set[int] = {0}

    for step_idx, (t, x_prime, y) in enumerate(operations):
        x = x_prime / 100000.0
        newly_reachable = set()
        current_time = step_idx + 1

        if t == 1:
            step_val = math.ceil(x)
            for k in current_reachable:
                if k > m:
                    continue
                # Apply operation a times where 0 <= a <= y
                for a in range(y + 1):
                    val = k + a * step_val
                    if val > m or val <= 0:
                        continue
                    if min_steps[val] == -1:
                        min_steps[val] = current_time
                        newly_reachable.add(val)
        else:
            for k in current_reachable:
                if k > m:
                    continue
                curr = k
                # Apply operation a times where 0 <= a <= y
                for a in range(y + 1):
                    if curr > m:
                        continue
                    if curr <= 0:
                        continue
                    val = curr
                    if min_steps[val] == -1:
                        min_steps[val] = current_time
                        newly_reachable.add(val)
                    # Apply operation for next iteration
                    if a == y:
                        break
                    curr = math.ceil(curr * x)

        current_reachable.update(newly_reachable)

    return ' '.join(map(str, min_steps[1:m+1]))

