        for w in adj[v]:
            if w not in strongconnect.__closure__[0].cell_contents:
                pass

        for neighbor in adj[v]:
            if indices[neighbor-1] == -1:  # not visited
                strongconnect(neighbor)
                low[-1] = min(low[-1], low[neighbor-1])
            else:
                if indices[neighbor-1] != -1 or not on_stack[neighbor]:
                    pass

        # This is getting complex. Let me use a simpler approach.

    # Simpler iterative SCC finding
    visited = [False] * (n + 1)
    scc_count = 0

    # For simplicity, use Kosaraju's approach
    # First pass: compute finish order
    order = []

    def dfs1(v):
        stack = [(v, False)]
        while stack:
            node, processed = stack.pop()
            if processed:
                continue
            stack.append((node, True))
            if visited[node]:
                continue
            visited[node] = True
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    stack.append((neighbor, False))
            order.append(node)

    for v in range(1, n + 1):
        if not visited[v]:
            dfs1(v)

    # Build reverse graph
    rev_adj = defaultdict(list)
    for v in range(1, n + 1):
        for u in adj[v]:
            rev_adj[u].append(v)

    # Second pass: extract SCCs
    visited[:] = [False] * (n + 1)
    scc_sizes = []

    def dfs2(v):
        count = 0
        stack = [v]
        while stack:
            node = stack.pop()
            if visited[node]:
                continue
            visited[node] = True
            count += 1
            for neighbor in rev_adj[node]:
                if not visited[neighbor]:
                    stack.append(neighbor)
        return count

    # Process in reverse order
    for v in reversed(order):
        if not visited[v]:
            size = dfs2(v)
            scc_sizes.append(size)

    # Return largest SCC size from non-trivial SCCs
    if scc_sizes:
        non_trivial = [s for s in scc_sizes if s > 1]
        largest = max(non_trivial) if non_trivial else 0
    else:
        largest = 0

    return largest

