        if p == 1:
            return 0
        def extended_gcd(a, b):
            if b == 0:
                return a, 1, 0
            else:
                g, x, y = extended_gcd(b, a % b)
                return g, y, x - (a // b) * y

        g, x, y = extended_gcd(a % p, p)
        if g != 1:
            return 0
        return (x % p + p) % p

    def nCr_mod(a, b, fact, invFact, mod):
        if b < 0 or b > a:
            return 0
        return fact[a] * invFact[b] % mod * invFact[a - b] % mod

