    limit = n + 5
    fact = [1] * limit
    invFact = [1] * limit

    for i in range(1, limit):
        fact[i] = fact[i-1] * i % p

    # Compute inverse factorial at limit-1 using Fermat's little theorem
    # If p is prime, a^(p-2) mod p is the inverse
    invFact[limit-1] = pow(fact[limit-1], p - 2, p)
    for i in range(limit-2, -1, -1):
        invFact[i] = invFact[i+1] * (i + 1) % p

    ans = 0

    # Iterate over possible values of a (50-yuan customers) and b (100-yuan customers)
    for a in range(n + 1):
        for b in range(a + 1):  # b cannot exceed a
