            # Check if remaining 50-yuan notes in range [l, r]
            if l <= a - b <= r:
                c = n - (a + b)  # VIP customers

                # Number of valid A-B sequences using Catalan-like formula
                # For a A's and b B's where no prefix has more B's than A's:
                # valid = (a - b + 1) / (a + 1) * C(a + b, a)
                if a + b == 0:
