import sys

# Solution code
def solution(input_string):
    """
    Solves the John Doe Free Market problem.
    Returns the maximum possible price and minimum number of days needed.
    """
    lines = input_string.strip().split('\n')
    n, d = map(int, lines[0].split())
    c = list(map(int, lines[1].split()))

    max_sum = sum(c)

    # reachable[i] = minimum days to achieve total value i
    # Start with value 0 at day 0
    reachable = {0: 0}

    # BFS approach - explore all reachable states
    # Each day, from any reachable value s, we can reach s + v where v is any item value
    # BUT the constraint: we can only "take" from the market if s + d >= new_total
    # So we can add item v if s + d >= s + v, i.e., v <= d

    # However, looking at the examples more carefully:
    # Example 2: values [1,2,3], d=5 -> 6 in 2 days
    # Day 1: can get item 1 (0+5>=1), now have value 1
    # Day 2: can get items 2,3 (1+5>=1+2, 1+5>=1+3)
    # 
    # So the rule is: from current value s, we can transition to a new subset sum t
    # if s + d >= t (we don't have to trade, we can just add items)

    from collections import deque

    min_days_to = {0: 0}  # (value, days)
    queue = deque([(0, 0)])

    while queue:
        current_val, days = queue.popleft()

        # Can we reach target max_sum?
        if current_val == max_sum:
            return f"{max_sum} {days}"

        # From current state, we can add items to reach new values
        # The constraint: new_value <= current_val + d
        for i in range(current_val + 1, min(max_sum + 1, current_val + d + 2)):
            if i in min_days_to:
                continue  # Already reached this value, possibly in fewer days
            # Check if we can actually form value i
            if can_form_value(i, c):
                if i not in min_days_to or min_days_to[i] > days + 1:
                    min_days_to[i] = days + 1
                    queue.append((i, days + 1))

    max_reachable = max(min_days_to.keys())
    if max_reachable == 0:
        return "0 1"

    return f"{max_reachable} {min_days_to[max_reachable]}"


def can_form_value(target, items):
    """Check if target can be formed as a sum of subset of items."""
    can = [False] * (target + 1)
    can[0] = True

    for item in items:
        for j in range(target, item - 1, -1):
            if can[j - item]:
                can[j] = True
                if j == target:
                    return True

    return can[target]


# Optimized solution for the actual problem constraints
def solution_optimized(input_string):
    """
    Optimized solution handling the actual constraints.
    """
    lines = input_string.strip().split('\n')
    n, d = map(int, lines[0].split())
    c = list(map(int, lines[1].split()))

    # Sort items for better dp
    c.sort()
    max_sum = sum(c)

    # Compute which values are reachable (subset sum problem)
    dp = {0}
    for item in c:
        new_states = set()
        for s in dp:
            new_states.add(s + item)
        for s in new_states:
            if s <= max_sum:
                dp.add(s)

    if not dp:
        return "0 1"

    max_reachable = max(dp)

    # Compute minimum days to reach each value
    # From value s, we can reach any value t <= s + d
    # We do a BFS-like expansion day by day

    day_reachable = {0: 0}  # value -> min_days

    for day in range(1, max_sum + 1):
        current_set = set()
        for val, d_val in day_reachable.items():
            if d_val > day:
                continue  # Already took too many days
            for t in dp:
                if val + d >= t and t >= val:  # Valid transition
                    if t not in day_reachable or day_reachable[t] > day:
                        day_reachable[t] = day
                        current_set.add(t)

        # If no progress this day, all reached
        if not current_set:
            break

    if not day_reachable:
        return f"{max_reachable} 1"

    return f"{max_reachable} {day_reachable[max_reachable]}"


def solution_final(input_string):
    """
    Final clean solution.
    """
    lines = input_string.strip().split('\n')
    n, d = map(int, lines[0].split())
    c = list(map(int, lines[1].split()))

    # Maximum possible sum (take all items)
    max_sum = sum(c)

    # DP: track all reachable subset sums
    reachable = {0}
    for item in c:
        new_states = set()
        for s in reachable:
            new_states.add(s + item)
        for s in new_states:
            if s <= max_sum:
                reachable.add(s)

    max_reachable = max(reachable)

    # BFS for minimum days
    # Each day expands reachable values by up to d
    min_days_to = {0: 0}
    queue = [0]

    for _ in range(max_reachable + 1):
        if min_days_to:
            for _ in range(len(queue)):
                val = queue.pop(0)
                if val == max_reachable:
                    return f"{max_reachable} {min_days_to[val]}"

                # From val, we can reach any t in reachable where val + d >= t
                for t in reachable:
                    if t >= val and val + d >= t:
                        if t not in min_days_to or min_days_to[t] > min_days_to[val] + 1:
                            min_days_to[t] = min_days_to[val] + 1
                            queue.append(t)

            # Large leaps allowed - continue expanding
            for val in list(queue):
                if val > max_reachable:
                    del min_days_to[val]
                    if val in queue:
                        queue.remove(val)

            queue = []
            break

    return f"{max_reachable} {min_days_to.get(max_reachable, 1)}"


