def count_valid_sequences(n_rows, curr_left, curr_right):
    """Count number of valid sequences where next interval is [curr_left, curr_right]"""
    if n_rows == 0 or curr_left >= curr_right or curr_left < 1 or curr_right > n_rows:
        return 1 if (curr_left < curr_right <= curr_right) else 0

    count = 0
    for prev_left in range(1, curr_left + 1):
        for prev_right in range(max(curr_left, 1), min(curr_right + 1, n_rows) + 1):
            if prev_left < prev_right:
                count = (count + 1) % MOD

    return count

def solution(input_str):
    n, m = map(int, input_str.strip().split())

    if m < 2:
        return "0\n"

    ans = 0

    # Iterate over all possible t values
    for t in range(1, n + 1):
        # dp[l][r] = number of ways to choose intervals for [l, t] ending at [l, r]
        dp_left = [[0] * (m + 2) for _ in range(n + 2)]

        for l in range(t, 0, -1):
            for r in range(l + 1, m + 1):
                dp_left[l][r] += dp_left[l + 1][r]
                dp_left[l][r] += dp_left[l + 1][r - 1]

        # dp[r][r] = number of ways to choose intervals for [t, r] ending at [t, r]
        dp_right = [[0] * (m + 2) for _ in range(n + 2)]

        for pos in range(t, n + 1):
            for r in range(pos + 1, m + 1):
                dp_right[pos][r] += dp_right[pos + 1][r]
                dp_right[pos][r] += dp_right[pos + 1][r - 1]

        # Calculate answer
        for L in range(1, m):
            for R in range(L + 1, m + 1):
                # Contribution from this turning point
                ways_left = dp_left[t][L]
                ways_right = dp_right[t][R]
                if ways_left > 0 and ways_right > 0:
                    ans = (ans + ways_left * ways_right) % MOD

    return f"{ans}\n"

